{
  "name": "RIGOL DSA800 频谱分析仪",
  "name_en": "Rigol DSA800 Spectrum Analyzer",
  "manufacturer": "Rigol",
  "description": "RIGOL DSA800 系列台式频谱分析仪，用于扫描和测量射频信号频谱。该设备支持设置起止频率、中心频率与扫宽、参考电平与幅度刻度、输入衰减、前置放大器、标记与峰值搜索、分辨率带宽/视频带宽，并可读取迹线数据用于实验分析。",
  "description_en": "The Rigol DSA800 is a benchtop spectrum analyzer for scanning and measuring RF signal spectra. It supports start/stop/center/span frequency settings, reference level and amplitude scaling, input attenuation, preamplifier control, markers and peak search, resolution/video bandwidth configuration, and trace acquisition for laboratory analysis.",
  "actions": [
    {
      "action_name": "auto-reset",
      "description": "复位频谱分析仪到默认状态。",
      "description_en": "Reset the spectrum analyzer to its default state."
    },
    {
      "action_name": "auto-clear_buffers",
      "description": "清除设备通信或状态缓冲区。",
      "description_en": "Clear the instrument communication or status buffers."
    },
    {
      "action_name": "auto-autoset",
      "description": "自动设置测量参数以适配当前输入信号。",
      "description_en": "Automatically configure measurement settings for the current input signal."
    },
    {
      "action_name": "auto-operationComplete",
      "description": "查询或等待当前设备操作完成。",
      "description_en": "Query or wait for the current instrument operation to complete."
    },
    {
      "action_name": "auto-preamplifier",
      "description": "开启或关闭前置放大器。",
      "description_en": "Enable or disable the preamplifier."
    },
    {
      "action_name": "auto-attenuation",
      "description": "设置输入衰减。",
      "description_en": "Set the input attenuation."
    },
    {
      "action_name": "auto-frequencyStart",
      "description": "设置扫描起始频率。",
      "description_en": "Set the sweep start frequency."
    },
    {
      "action_name": "auto-frequencyStop",
      "description": "设置扫描终止频率。",
      "description_en": "Set the sweep stop frequency."
    },
    {
      "action_name": "auto-frequencyCenter",
      "description": "设置中心频率。",
      "description_en": "Set the center frequency."
    },
    {
      "action_name": "auto-frequencySpan",
      "description": "设置频率扫宽。",
      "description_en": "Set the frequency span."
    },
    {
      "action_name": "auto-amplitudeReference",
      "description": "设置参考电平。",
      "description_en": "Set the reference level."
    },
    {
      "action_name": "auto-amplitudeOffset",
      "description": "设置幅度偏移。",
      "description_en": "Set the amplitude offset."
    },
    {
      "action_name": "auto-amplitudeScale",
      "description": "设置幅度刻度。",
      "description_en": "Set the amplitude scale."
    },
    {
      "action_name": "auto-markerToggle",
      "description": "开启或关闭指定标记。",
      "description_en": "Enable or disable the specified marker."
    },
    {
      "action_name": "auto-markerTrace",
      "description": "将指定标记关联到某条迹线。",
      "description_en": "Assign the specified marker to a trace."
    },
    {
      "action_name": "auto-markerMode",
      "description": "设置指定标记的工作模式。",
      "description_en": "Set the operating mode of the specified marker."
    },
    {
      "action_name": "auto-markerReadoutMode",
      "description": "设置指定标记的读出模式。",
      "description_en": "Set the readout mode of the specified marker."
    },
    {
      "action_name": "auto-markerTrack",
      "description": "开启或关闭指定标记的跟踪功能。",
      "description_en": "Enable or disable tracking for the specified marker."
    },
    {
      "action_name": "auto-markerAmplitude",
      "description": "读取指定标记处的幅度。",
      "description_en": "Read the amplitude at the specified marker."
    },
    {
      "action_name": "auto-markerFrequency",
      "description": "设置指定标记的频率位置。",
      "description_en": "Set the frequency position of the specified marker."
    },
    {
      "action_name": "auto-peakSearch",
      "description": "开启、关闭或触发峰值搜索功能。",
      "description_en": "Enable, disable, or trigger the peak search function."
    },
    {
      "action_name": "auto-peakSet",
      "description": "将指定通道的标记设到峰值位置。",
      "description_en": "Set the marker on the specified channel to a peak position."
    },
    {
      "action_name": "auto-peakNext",
      "description": "将指定通道的标记移动到下一个峰值。",
      "description_en": "Move the marker on the specified channel to the next peak."
    },
    {
      "action_name": "auto-peakThreshold",
      "description": "设置峰值搜索门限。",
      "description_en": "Set the peak search threshold."
    },
    {
      "action_name": "auto-peakExcursion",
      "description": "设置峰值搜索的最小峰间起伏条件。",
      "description_en": "Set the minimum excursion used for peak search."
    },
    {
      "action_name": "auto-peakTable",
      "description": "读取峰值表，返回峰值频率和幅度信息。",
      "description_en": "Read the peak table and return peak frequency and amplitude information."
    },
    {
      "action_name": "auto-bandwidthSweepTime",
      "description": "设置扫描时间。",
      "description_en": "Set the sweep time."
    },
    {
      "action_name": "auto-bandwidthResolution",
      "description": "设置分辨率带宽。",
      "description_en": "Set the resolution bandwidth."
    },
    {
      "action_name": "auto-bandwidthVideo",
      "description": "设置视频带宽。",
      "description_en": "Set the video bandwidth."
    },
    {
      "action_name": "auto-getTrace",
      "description": "读取指定通道的频谱迹线数据。",
      "description_en": "Acquire the spectrum trace data from the specified channel."
    }
  ],
  "tag_hints": [
    "spectrum analysis",
    "RF measurement",
    "trace acquisition",
    "marker measurements",
    "peak search",
    "RBW/VBW control",
    "GPIB instrument"
  ]
}

